source='''def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    row_groups = {}
    col_groups = {}
    for r, c in points:
        row_groups.setdefault(r, []).append(c)
        col_groups.setdefault(c, []).append(r)
    rows = [(r, cs) for r, cs in row_groups.items() if len(cs) >= 2]
    cols = [(c, rs) for c, rs in col_groups.items() if len(rs) >= 2]
    if rows:
        axis, vals = max(rows, key=lambda x: len(x[1]))
        lo, hi = min(vals), max(vals)
        for c in range(lo, hi + 1):
            if out[axis][c] == 0:
                out[axis][c] = 3
        for r, c in points:
            if r != axis and out[r][c] == 2:
                step = 1 if axis > r else -1
                rr = r + step
                while rr != axis:
                    if out[rr][c] == 0:
                        out[rr][c] = 3
                    rr += step
    elif cols:
        axis, vals = max(cols, key=lambda x: len(x[1]))
        lo, hi = min(vals), max(vals)
        for r in range(lo, hi + 1):
            if out[r][axis] == 0:
                out[r][axis] = 3
        for r, c in points:
            if c != axis and out[r][c] == 2:
                step = 1 if axis > c else -1
                cc = c + step
                while cc != axis:
                    if out[r][cc] == 0:
                        out[r][cc] = 3
                    cc += step
    return out
'''
